            next_c = field_storage.KPV_SCRAMBLER_CTRL.lock.value | (decoded_wr_data[1:1] & decoded_wr_biten[1:1]);
            load_next_c = '1;
        end else if(hwif_in.KPV_SCRAMBLER_CTRL.lock.hwclr) begin // HW Clear
            next_c = '0;
            load_next_c = '1;
        end
        field_combo.KPV_SCRAMBLER_CTRL.lock.next = next_c;
        field_combo.KPV_SCRAMBLER_CTRL.lock.load_next = load_next_c;
    end
    always_ff @(posedge clk or negedge arst_n) begin
        if(~arst_n) begin
            field_storage.KPV_SCRAMBLER_CTRL.lock.value <= 1'h0;
        end else begin
            if(field_combo.KPV_SCRAMBLER_CTRL.lock.load_next) begin
                field_storage.KPV_SCRAMBLER_CTRL.lock.value <= field_combo.KPV_SCRAMBLER_CTRL.lock.next;
            end
        end
    end
    assign hwif_out.KPV_SCRAMBLER_CTRL.lock.value = field_storage.KPV_SCRAMBLER_CTRL.lock.value;

    //--------------------------------------------------------------------------
    // Write response
    //--------------------------------------------------------------------------
    always_comb begin
        automatic logic wr_ack;
        wr_ack = '0;
        for(int i0=0; i0<64; i0++) begin
            wr_ack |= hwif_in.KEY_ENTRY[i0].wr_ack;
        end
        external_wr_ack = wr_ack;
    end
    assign cpuif_wr_ack = external_wr_ack | (decoded_req & decoded_req_is_wr & ~decoded_req_is_external);
    // Writes are always granted with no error response
    assign cpuif_wr_err = decoded_err;

    //--------------------------------------------------------------------------
    // Readback
    //--------------------------------------------------------------------------
    logic readback_external_rd_ack_c;
    always_comb begin
        automatic logic rd_ack;
        rd_ack = '0;
        for(int i0=0; i0<64; i0++) begin
            rd_ack |= hwif_in.KEY_ENTRY[i0].rd_ack;
        end
        readback_external_rd_ack_c = rd_ack;
    end

    logic readback_external_rd_ack;

    assign readback_external_rd_ack = readback_external_rd_ack_c;

    logic [12:0] rd_mux_addr;
    logic [12:0] pending_rd_addr;
    // Hold read mux address to guarantee it is stable throughout any external accesses
    always_ff @(posedge clk) begin
        if(~hwif_in.WARM_RST_N) begin
            pending_rd_addr <= '0;
        end else begin
            if(decoded_req) pending_rd_addr <= decoded_addr;
        end
    end
    assign rd_mux_addr = decoded_req ? decoded_addr : pending_rd_addr;

    logic readback_err;
    logic readback_done;
    logic [31:0] readback_data;
    always_comb begin
        automatic logic [31:0] readback_data_var;
        readback_data_var = '0;
        for(int i0=0; i0<64; i0++) begin
            if((rd_mux_addr >= 13'h0 + (13)'(i0) * 13'h40) && (rd_mux_addr <= 13'h0 + (13)'(i0) * 13'h40 + 13'h3f)) begin
                readback_data_var = hwif_in.KEY_ENTRY[i0].rd_data;
            end
        end
        for(int i0=0; i0<64; i0++) begin
            if(rd_mux_addr == 13'h1000 + (13)'(i0) * 13'h4) begin
                readback_data_var[0] = field_storage.CTRL[i0].lock_write.value;
                readback_data_var[1] = field_storage.CTRL[i0].lock_use.value;
                readback_data_var[2] = field_storage.CTRL[i0].erase.value;
                readback_data_var[3] = field_storage.CTRL[i0].seal.value;
                readback_data_var[31:4] = 28'h0;
            end
        end
        if(rd_mux_addr == 13'h1100) begin
            readback_data_var[31:0] = field_storage.KPV_SCRAMBLER_KEY.key.value;
        end
        if(rd_mux_addr == 13'h1104) begin
            readback_data_var[0] = field_storage.KPV_SCRAMBLER_CTRL.enable.value;
            readback_data_var[1] = field_storage.KPV_SCRAMBLER_CTRL.lock.value;
            readback_data_var[31:2] = 30'h0;
        end
        readback_data = readback_data_var;
        readback_done = decoded_req & ~decoded_req_is_wr & ~decoded_req_is_external;
        readback_err = decoded_err;
    end

    assign external_rd_ack = readback_external_rd_ack;
    assign cpuif_rd_ack = readback_done | readback_external_rd_ack;
    assign cpuif_rd_data = readback_data;
    assign cpuif_rd_err = readback_err;
endmodule
